}

exercises.solution:
class Rettangolo {
  final double larghezza;
  final double altezza;

  Rettangolo(this.larghezza, this.altezza);

  double calcolaArea() => larghezza * altezza;
}

void main() {
  var r = Rettangolo(5, 3);
  print('Area: ${r.calcolaArea()}');
}

