exercises.solution:
double dividi(double a, double b) {
  if (b == 0) {
    throw Exception('Divisione per zero non permessa');
  }
  return a / b;
}

void main() {
  try {
    print(dividi(10, 0));
  } catch (e) {
    print('Errore: $e');
  }
}

