void main() {
  var u = Utente('Mario');
  u.log('Accesso effettuato');
}

exercises.solution:
mixin Loggable {
  void log(String messaggio) {
    print('[LOG] $messaggio');
  }
}

class Utente with Loggable {
  final String nome;
  Utente(this.nome);
}

void main() {
  var u = Utente('Mario');
  u.log('Accesso effettuato');
}
